completion:
integer k;
integer r, c;
integer count;
reg [255:0] next_q;

always @(*) begin
    for (k = 0; k < 256; k = k + 1) begin
        r = k >> 4;
        c = k & 15;
        count = q[(((r+1)&15) << 4) + ((c+1)&15)] +
                q[(((r+1)&15) << 4) + c] +
                q[(((r+1)&15) << 4) + ((c+15)&15)] +
                q[(r << 4) + ((c+1)&15)] +
                q[(r << 4) + ((c+15)&15)] +
                q[(((r+15)&15) << 4) + ((c+1)&15)] +
                q[(((r+15)&15) << 4) + c] +
                q[(((r+15)&15) << 4) + ((c+15)&15)];

        if (count == 2)
            next_q[k] = q[k];
        else if (count == 3)
            next_q[k] = 1'b1;
        else
            next_q[k] = 1'b0;
    end
end

always @(posedge clk) begin
    if (load)
        q <= data;
    else
        q <= next_q;
end

endmodule
